# Exact Wharton/S10 CPU probe transport. Paste into the private notebook's empty code cell.
# This reconstructs and executes the unchanged reviewed notebook; no package installation/network.
import ast as _s10_ast
import base64 as _s10_base64
import hashlib as _s10_hashlib
import json as _s10_json
import os as _s10_os
import platform as _s10_platform
import signal as _s10_signal
import uuid as _s10_uuid
from datetime import datetime as _s10_datetime, timezone as _s10_timezone
from pathlib import Path as _s10_Path

S10_NOTEBOOK_SHA256 = '91d1786c6aa87760669601e086387f7085be9c80b18d8e0ae77592776ca422d3'
S10_NOTEBOOK_BYTES = 635980
S10_NOTEBOOK_B64 = ''


def _s10_before_deadline():
    deadline = _s10_datetime(2026, 10, 16, 16, 30, tzinfo=_s10_timezone.utc)
    if (deadline - _s10_datetime.now(_s10_timezone.utc)).total_seconds() <= 10:
        raise RuntimeError("Tonight deadline leaves no safe execution margin; stop the Kaggle session")


def _s10_probe_only(namespace):
    expected = {"MODE": "probe", "ACCELERATOR": "None", "RETRIEVAL_RECEIPT": None,
                "RESTORE_ARCHIVE": None, "RESTORE_ARCHIVE_SHA256": None}
    if any(namespace.get(key, object()) != value for key, value in expected.items()):
        raise RuntimeError("Transport is probe-only; reviewed notebook parameters changed")


def _s10_transport_timeout(_signal, _frame):
    raise TimeoutError("bounded exact-notebook transport setup expired")

_s10_before_deadline()
_s10_signal.signal(_s10_signal.SIGALRM, _s10_transport_timeout)
_s10_signal.setitimer(_s10_signal.ITIMER_REAL, min(30, (_s10_datetime(2026, 10, 16, 16, 30, tzinfo=_s10_timezone.utc) - _s10_datetime.now(_s10_timezone.utc)).total_seconds() - 10))
if _s10_platform.system() != "Linux" or not _s10_Path("/kaggle/working").is_dir():
    raise RuntimeError("This transport only runs inside the intended Kaggle Linux notebook")
if _s10_Path("/dev/nvidia0").exists() or list(_s10_Path("/proc/driver/nvidia/gpus").glob("*")):
    raise RuntimeError("CPU probe requires accelerator None; visible NVIDIA device refused")
if len(S10_NOTEBOOK_B64) > 2 * 2**20:
    raise RuntimeError("Embedded notebook exceeds bounded transport size")
_s10_payload = _s10_base64.b64decode(S10_NOTEBOOK_B64, validate=True)
if len(_s10_payload) != S10_NOTEBOOK_BYTES or _s10_hashlib.sha256(_s10_payload).hexdigest() != S10_NOTEBOOK_SHA256:
    raise RuntimeError("Exact finalized notebook transport hash/size mismatch")
_s10_notebook = _s10_json.loads(_s10_payload)
if (_s10_notebook.get("nbformat"), _s10_notebook.get("nbformat_minor")) != (4, 5):
    raise RuntimeError("Unexpected finalized notebook format")
_s10_code_cells = [cell for cell in _s10_notebook["cells"] if cell["cell_type"] == "code"]
_s10_headings = ["".join(cell["source"]).splitlines()[0] for cell in _s10_notebook["cells"]
                 if cell["cell_type"] == "markdown" and "".join(cell["source"]).startswith("# ")]
if len(_s10_code_cells) != 8 or len(_s10_headings) != 12:
    raise RuntimeError("Expected exactly eight code cells and twelve reviewed sections")
_s10_compiled = []
for _s10_index, _s10_cell in enumerate(_s10_code_cells, 1):
    _s10_source = "".join(_s10_cell["source"])
    _s10_tree = _s10_ast.parse(_s10_source, filename=f"FREM_S10_TONIGHT_CPU.ipynb:cell{_s10_index}")
    _s10_compiled.append(compile(_s10_tree, f"FREM_S10_TONIGHT_CPU.ipynb:cell{_s10_index}", "exec"))
_s10_config = {node.targets[0].id: _s10_ast.literal_eval(node.value)
               for node in _s10_ast.parse("".join(_s10_code_cells[0]["source"])).body}
_s10_probe_only(_s10_config)
_s10_root = _s10_Path("/kaggle/working/frem_s10_tonight_20261016")
_s10_root.mkdir(parents=True, exist_ok=True)
_s10_transport_charge = _s10_root / ("bootstrap-transport-" + _s10_uuid.uuid4().hex + ".json")
with _s10_transport_charge.open("x") as _s10_charge_stream:
    _s10_json.dump({"reserved_seconds": 60}, _s10_charge_stream)
_s10_target = _s10_root / "FREM_S10_TONIGHT_CPU.ipynb"
if _s10_target.exists():
    if _s10_target.is_symlink() or _s10_target.read_bytes() != _s10_payload:
        raise RuntimeError("Existing notebook differs; preserve it and stop")
else:
    with _s10_target.open("xb") as _s10_stream:
        _s10_stream.write(_s10_payload)
        _s10_stream.flush()
        _s10_os.fsync(_s10_stream.fileno())
print(_s10_json.dumps({"transport": "EXACT_NOTEBOOK_CPU_PROBE_ONLY", "notebook_sha256": S10_NOTEBOOK_SHA256,
                       "notebook_path": str(_s10_target), "code_cells_ast_verified": 8,
                       "scientific_status": "NOT_EVALUATED"}), flush=True)
_s10_signal.setitimer(_s10_signal.ITIMER_REAL, 0)
_s10_namespace = {"__name__": "__s10_exact_notebook_transport__"}
_s10_next_code = 0
for _s10_cell in _s10_notebook["cells"]:
    _s10_before_deadline()
    if _s10_cell["cell_type"] == "markdown":
        print("\n" + "".join(_s10_cell["source"]).splitlines()[0], flush=True)
    elif _s10_cell["cell_type"] == "code":
        if _s10_next_code:
            _s10_probe_only(_s10_namespace)
        print(f"Executing exact notebook code cell {_s10_next_code + 1}/8", flush=True)
        exec(_s10_compiled[_s10_next_code], _s10_namespace, _s10_namespace)
        _s10_probe_only(_s10_namespace)
        _s10_next_code += 1
print("Probe cells finished. Save output for this private version, retrieve and hash-check the probe, then explicitly stop the platform session. No numerical campaign was authorized by this transport.", flush=True)
